-- Authorized reset of all old shop business data. Storage objects must first be removed via Storage API.
DO $scope$ BEGIN IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='shop-mobile-images') THEN RAISE EXCEPTION 'Storage must be empty before reset'; END IF; END $scope$;
DO $drop$ DECLARE r record; BEGIN
 FOR r IN SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.proname LIKE 'shop_%' LOOP EXECUTE format('DROP FUNCTION IF EXISTS %I.%I(%s) CASCADE',r.nspname,r.proname,r.args); END LOOP;
 FOR r IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'shop_%' LOOP EXECUTE format('DROP TABLE IF EXISTS public.%I CASCADE',r.tablename); END LOOP;
 IF to_regclass('public.shop_mobile_order_seq') IS NOT NULL THEN DROP SEQUENCE public.shop_mobile_order_seq; END IF;
END $drop$;
SET LOCAL search_path=public,pg_temp;
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC;
CREATE TABLE app_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,category_id BIGINT,cost_price BIGINT NOT NULL DEFAULT 0 CHECK(cost_price>=0),sale_price BIGINT NOT NULL DEFAULT 0 CHECK(sale_price>=0),description TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE product_variants(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL,sku TEXT NOT NULL UNIQUE,size TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')), cost_price BIGINT NOT NULL DEFAULT 0 CHECK(cost_price>=0), sale_price BIGINT NOT NULL DEFAULT 0 CHECK(sale_price>=0),UNIQUE(product_id,size),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE product_images(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL,variant_id BIGINT,file_path TEXT NOT NULL,sort_order BIGINT NOT NULL DEFAULT 0,is_primary BIGINT NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)),created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE inventory_transactions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,variant_id BIGINT NOT NULL,transaction_type TEXT NOT NULL CHECK(transaction_type IN ('OPENING','IMPORT','ADJUST_PLUS','ADJUST_MINUS')),quantity BIGINT NOT NULL CHECK(quantity>0),unit_cost BIGINT CHECK(unit_cost IS NULL OR unit_cost>=0),note TEXT,created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_variants_product ON product_variants(product_id);
CREATE INDEX idx_variants_size ON product_variants(size);
CREATE INDEX idx_inventory_variant ON inventory_transactions(variant_id);
CREATE INDEX idx_images_product_variant ON product_images(product_id,variant_id);
CREATE TABLE sales_orders(
    id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CANCELLED_DRAFT')),
    version BIGINT NOT NULL DEFAULT 1 CHECK(version>0),
    discount BIGINT NOT NULL CHECK(discount BETWEEN 0 AND 9007199254740991),
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS'))
   );
CREATE TABLE sales_order_images(
    order_id TEXT NOT NULL REFERENCES sales_orders(id), image_id BIGINT NOT NULL REFERENCES product_images(id),
    product_id BIGINT NOT NULL REFERENCES products(id),variant_id BIGINT NOT NULL REFERENCES product_variants(id),
    product_name TEXT NOT NULL,product_code TEXT NOT NULL,size TEXT NOT NULL,sku TEXT NOT NULL,
    unit_price BIGINT NOT NULL CHECK(unit_price BETWEEN 0 AND 9007199254740991),
    unit_cost BIGINT CHECK(unit_cost IS NULL OR unit_cost BETWEEN 0 AND 9007199254740991),
    position BIGINT NOT NULL CHECK(position>=0),PRIMARY KEY(order_id,image_id),UNIQUE(order_id,position)
   );
CREATE INDEX idx_sales_orders_status_date ON sales_orders(status,created_at);
CREATE TABLE sales_operations(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,input_hash TEXT NOT NULL,payload TEXT NOT NULL,payload_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PREPARED','SOLD','ROLLED_BACK')),created_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE sales_confirmations(order_id TEXT PRIMARY KEY REFERENCES sales_orders(id),operation_id TEXT NOT NULL UNIQUE REFERENCES sales_operations(id),version BIGINT NOT NULL,subtotal BIGINT NOT NULL,discount BIGINT NOT NULL CHECK(discount>=0 AND discount<=subtotal),total BIGINT NOT NULL CHECK(total=subtotal-discount),note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE sales_units(image_id BIGINT PRIMARY KEY REFERENCES product_images(id),order_id TEXT NOT NULL REFERENCES sales_confirmations(order_id),variant_id BIGINT NOT NULL REFERENCES product_variants(id),snapshot TEXT NOT NULL,source_hash TEXT NOT NULL,archive_path TEXT NOT NULL,archive_hash TEXT NOT NULL);
CREATE TABLE sales_ledger(image_id BIGINT PRIMARY KEY REFERENCES sales_units(image_id),order_id TEXT NOT NULL REFERENCES sales_confirmations(order_id),variant_id BIGINT NOT NULL REFERENCES product_variants(id),transaction_type TEXT NOT NULL CHECK(transaction_type='SALE'),quantity BIGINT NOT NULL CHECK(quantity=1),unit_cost BIGINT CHECK(unit_cost IS NULL OR unit_cost>=0),created_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE shop_customers(
 id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,phone_key TEXT NOT NULL,
 address TEXT NOT NULL,note TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,
 created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE INDEX idx_customers_phone ON shop_customers(phone_key);
CREATE TABLE order_contacts(
 order_id TEXT PRIMARY KEY REFERENCES sales_orders(id),customer_id TEXT REFERENCES shop_customers(id),
 recipient_name TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',
 shipping_fee BIGINT NOT NULL DEFAULT 0 CHECK(shipping_fee BETWEEN 0 AND 9007199254740991));
CREATE TABLE order_finance(order_id TEXT PRIMARY KEY REFERENCES sales_orders(id),version BIGINT NOT NULL CHECK(version>0),method TEXT NOT NULL CHECK(method IN ('COD','TRANSFER','CASH')),delivery TEXT NOT NULL CHECK(delivery IN ('NEW','SHIPPED','DELIVERED','FAILED')),tracking TEXT NOT NULL DEFAULT '');
CREATE TABLE finance_entries(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES sales_orders(id),request_key TEXT NOT NULL UNIQUE,input_hash TEXT NOT NULL,payload TEXT NOT NULL,sequence BIGINT NOT NULL CHECK(sequence>0),kind TEXT NOT NULL CHECK(kind IN ('RECEIPT','REFUND','CREDIT')),amount BIGINT NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991),method TEXT NOT NULL CHECK(method IN ('COD','TRANSFER','CASH')),note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),UNIQUE(order_id,sequence));
CREATE TABLE aftercare_cases(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES sales_orders(id),request_key TEXT NOT NULL UNIQUE,input_hash TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('RETURN','EXCHANGE','SUPPORT')),note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('OPEN','RESOLVED')),resolution TEXT NOT NULL DEFAULT '',version BIGINT NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')));
CREATE INDEX finance_order ON finance_entries(order_id,created_at);
CREATE INDEX aftercare_order ON aftercare_cases(order_id,created_at);
CREATE TABLE stocktake_sessions(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,input_hash TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('OPEN','CLOSED','CANCELLED')),version BIGINT NOT NULL CHECK(version>0),fingerprint TEXT NOT NULL,snapshot_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(to_char(timezone('UTC',now()),'YYYY-MM-DD HH24:MI:SS')),closed_at TEXT,conclusion TEXT NOT NULL DEFAULT '');
CREATE TABLE stocktake_rows(session_id TEXT NOT NULL REFERENCES stocktake_sessions(id),variant_id BIGINT NOT NULL REFERENCES product_variants(id),snapshot TEXT NOT NULL,counted BIGINT CHECK(counted BETWEEN 0 AND 1000000),note TEXT NOT NULL DEFAULT '',PRIMARY KEY(session_id,variant_id));
CREATE VIEW inventory_stock WITH (security_invoker=true) AS SELECT variant_id,SUM(quantity) stock FROM (SELECT variant_id,CASE WHEN transaction_type='ADJUST_MINUS' THEN -quantity ELSE quantity END quantity FROM inventory_transactions UNION ALL SELECT variant_id,-quantity FROM sales_ledger) GROUP BY variant_id;
CREATE FUNCTION private.mc_sales_operation_payload_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Sale evidence is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sales_operation_payload_immutable() FROM PUBLIC; CREATE TRIGGER sales_operation_payload_immutable BEFORE UPDATE OF id,request_key,input_hash,payload,payload_hash ON sales_operations FOR EACH ROW EXECUTE FUNCTION private.mc_sales_operation_payload_immutable();
CREATE FUNCTION private.mc_sales_operation_terminal_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF OLD.status<>'PREPARED' THEN RAISE EXCEPTION 'Terminal sale is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sales_operation_terminal_immutable() FROM PUBLIC; CREATE TRIGGER sales_operation_terminal_immutable BEFORE UPDATE OF status ON sales_operations FOR EACH ROW EXECUTE FUNCTION private.mc_sales_operation_terminal_immutable();
CREATE FUNCTION private.mc_sales_operation_delete_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Sale evidence is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sales_operation_delete_immutable() FROM PUBLIC; CREATE TRIGGER sales_operation_delete_immutable BEFORE DELETE ON sales_operations FOR EACH ROW EXECUTE FUNCTION private.mc_sales_operation_delete_immutable();
CREATE FUNCTION private.mc_sold_order_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF EXISTS(SELECT 1 FROM sales_confirmations WHERE order_id=OLD.id) THEN RAISE EXCEPTION 'Sold order is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sold_order_update() FROM PUBLIC; CREATE TRIGGER sold_order_update BEFORE UPDATE ON sales_orders FOR EACH ROW EXECUTE FUNCTION private.mc_sold_order_update();
CREATE FUNCTION private.mc_sold_order_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF EXISTS(SELECT 1 FROM sales_confirmations WHERE order_id=OLD.id) THEN RAISE EXCEPTION 'Sold order is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sold_order_delete() FROM PUBLIC; CREATE TRIGGER sold_order_delete BEFORE DELETE ON sales_orders FOR EACH ROW EXECUTE FUNCTION private.mc_sold_order_delete();
CREATE FUNCTION private.mc_sold_items_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF EXISTS(SELECT 1 FROM sales_confirmations WHERE order_id=NEW.order_id) THEN RAISE EXCEPTION 'Sold order is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sold_items_insert() FROM PUBLIC; CREATE TRIGGER sold_items_insert BEFORE INSERT ON sales_order_images FOR EACH ROW EXECUTE FUNCTION private.mc_sold_items_insert();
