CREATE FUNCTION private.mc_sold_items_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF EXISTS(SELECT 1 FROM sales_confirmations WHERE order_id=OLD.order_id) THEN RAISE EXCEPTION 'Sold order is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sold_items_delete() FROM PUBLIC; CREATE TRIGGER sold_items_delete BEFORE DELETE ON sales_order_images FOR EACH ROW EXECUTE FUNCTION private.mc_sold_items_delete();
CREATE FUNCTION private.mc_sales_confirmations_update_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Sold evidence is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_sales_confirmations_update_immutable() FROM PUBLIC; CREATE TRIGGER sales_confirmations_update_immutable BEFORE UPDATE ON sales_confirmations FOR EACH ROW EXECUTE FUNCTION private.mc_sales_confirmations_update_immutable();
