CREATE FUNCTION private.mc_finance_no_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Finance ledger is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_finance_no_update() FROM PUBLIC; CREATE TRIGGER finance_no_update BEFORE UPDATE ON finance_entries FOR EACH ROW EXECUTE FUNCTION private.mc_finance_no_update();
CREATE FUNCTION private.mc_finance_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Finance ledger is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_finance_no_delete() FROM PUBLIC; CREATE TRIGGER finance_no_delete BEFORE DELETE ON finance_entries FOR EACH ROW EXECUTE FUNCTION private.mc_finance_no_delete();
CREATE FUNCTION private.mc_aftercare_identity_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Aftercare request is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_aftercare_identity_immutable() FROM PUBLIC; CREATE TRIGGER aftercare_identity_immutable BEFORE UPDATE OF id,order_id,request_key,input_hash,kind,note,created_at ON aftercare_cases FOR EACH ROW EXECUTE FUNCTION private.mc_aftercare_identity_immutable();
CREATE FUNCTION private.mc_aftercare_resolution_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF OLD.status='RESOLVED' OR NEW.status<>'RESOLVED' OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Aftercare resolution is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_aftercare_resolution_immutable() FROM PUBLIC; CREATE TRIGGER aftercare_resolution_immutable BEFORE UPDATE ON aftercare_cases FOR EACH ROW EXECUTE FUNCTION private.mc_aftercare_resolution_immutable();
CREATE FUNCTION private.mc_aftercare_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Aftercare history is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_aftercare_no_delete() FROM PUBLIC; CREATE TRIGGER aftercare_no_delete BEFORE DELETE ON aftercare_cases FOR EACH ROW EXECUTE FUNCTION private.mc_aftercare_no_delete();
CREATE FUNCTION private.mc_stocktake_final_no_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF OLD.status<>'OPEN' THEN RAISE EXCEPTION 'Final stocktake is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_final_no_update() FROM PUBLIC; CREATE TRIGGER stocktake_final_no_update BEFORE UPDATE ON stocktake_sessions FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_final_no_update();
CREATE FUNCTION private.mc_stocktake_identity_no_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Stocktake snapshot is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_identity_no_update() FROM PUBLIC; CREATE TRIGGER stocktake_identity_no_update BEFORE UPDATE OF id,request_key,input_hash,title,fingerprint,snapshot_hash,created_at ON stocktake_sessions FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_identity_no_update();
CREATE FUNCTION private.mc_stocktake_transition() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF NEW.version<>OLD.version+1 OR (NEW.status='OPEN' AND (NEW.closed_at IS NOT NULL OR NEW.conclusion<>'')) OR (NEW.status<>'OPEN' AND (NEW.closed_at IS NULL OR length(trim(NEW.conclusion))=0)) THEN RAISE EXCEPTION 'Invalid stocktake transition'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_transition() FROM PUBLIC; CREATE TRIGGER stocktake_transition BEFORE UPDATE ON stocktake_sessions FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_transition();
CREATE FUNCTION private.mc_stocktake_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Stocktake history is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_no_delete() FROM PUBLIC; CREATE TRIGGER stocktake_no_delete BEFORE DELETE ON stocktake_sessions FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_no_delete();
CREATE FUNCTION private.mc_stocktake_row_no_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF (SELECT status FROM stocktake_sessions WHERE id=OLD.session_id)<>'OPEN' OR NEW.session_id<>OLD.session_id OR NEW.variant_id<>OLD.variant_id OR NEW.snapshot<>OLD.snapshot THEN RAISE EXCEPTION 'Stocktake snapshot is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_row_no_update() FROM PUBLIC; CREATE TRIGGER stocktake_row_no_update BEFORE UPDATE ON stocktake_rows FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_row_no_update();
CREATE FUNCTION private.mc_stocktake_row_no_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN IF (SELECT status FROM stocktake_sessions WHERE id=NEW.session_id)<>'OPEN' THEN RAISE EXCEPTION 'Final stocktake is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_row_no_insert() FROM PUBLIC; CREATE TRIGGER stocktake_row_no_insert BEFORE INSERT ON stocktake_rows FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_row_no_insert();
CREATE FUNCTION private.mc_stocktake_row_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $fn$ BEGIN RAISE EXCEPTION 'Stocktake snapshot is immutable'; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $fn$; REVOKE ALL ON FUNCTION private.mc_stocktake_row_no_delete() FROM PUBLIC; CREATE TRIGGER stocktake_row_no_delete BEFORE DELETE ON stocktake_rows FOR EACH ROW EXECUTE FUNCTION private.mc_stocktake_row_no_delete();
CREATE TABLE cloud_members(user_id uuid PRIMARY KEY REFERENCES auth.users(id),role text NOT NULL CHECK(role IN ('owner','cashier','inventory','viewer')),enabled boolean NOT NULL DEFAULT true);
CREATE TABLE cloud_image_assets(image_id bigint PRIMARY KEY REFERENCES product_images(id),object_path text NOT NULL UNIQUE,bytes bigint NOT NULL CHECK(bytes BETWEEN 1 AND 150000),sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),revision text NOT NULL,ready boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_sync_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,request_key text NOT NULL UNIQUE,entity_type text NOT NULL,entity_id text NOT NULL,version bigint NOT NULL CHECK(version>0),payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_sync_cursors(instance_id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users(id),last_sequence bigint NOT NULL DEFAULT 0 CHECK(last_sequence>=0),core_version text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_requests(request_key text PRIMARY KEY,input_hash text NOT NULL,actor_id uuid NOT NULL REFERENCES auth.users(id),status text NOT NULL CHECK(status IN ('PENDING','COMMITTED','FAILED')),result jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_cloud_sync_entity ON cloud_sync_events(entity_type,entity_id,version);
CREATE INDEX idx_cloud_request_actor ON cloud_requests(actor_id);
CREATE INDEX idx_cloud_cursor_user ON cloud_sync_cursors(user_id);
ALTER TABLE cloud_members ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON cloud_members FROM PUBLIC,anon,authenticated;
GRANT SELECT ON cloud_members TO authenticated;
GRANT ALL ON cloud_members TO service_role;
CREATE POLICY own_membership ON cloud_members FOR SELECT TO authenticated USING(user_id=(select auth.uid()));

