INSERT INTO app_metadata(key,value) VALUES('schema_version','130'),('app_version','3.5.0-stage6-main-test'),('cloud_schema_version','1'),('cloud_status','FOUNDATION_NOT_CONNECTED'); INSERT INTO app_settings(key,value) VALUES('low_stock_threshold','2'); INSERT INTO cloud_members(user_id,role) SELECT id,'owner' FROM auth.users WHERE (SELECT count(*) FROM auth.users)=1;
ALTER PUBLICATION supabase_realtime ADD TABLE public.products,public.product_variants,public.product_images,public.cloud_image_assets,public.sales_orders,public.sales_confirmations,public.shop_customers,public.finance_entries,public.order_finance,public.stocktake_sessions,public.cloud_sync_events;
DROP POLICY IF EXISTS "v7_member_images_read" ON storage.objects; CREATE POLICY v7_member_images_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='shop-mobile-images' AND EXISTS(SELECT 1 FROM public.cloud_members WHERE user_id=(SELECT auth.uid()) AND enabled));
DO $pol$ DECLARE r record; BEGIN FOR r IN SELECT policyname FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname<>'v7_member_images_read' LOOP EXECUTE format('DROP POLICY %I ON storage.objects',r.policyname); END LOOP; END $pol$;
CREATE POLICY v7_inventory_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='shop-mobile-images' AND EXISTS(SELECT 1 FROM public.cloud_members WHERE user_id=(SELECT auth.uid()) AND enabled AND role IN ('owner','inventory')));
